import{c as s,Q as a,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const d="/assets/DIST_NORM%E6%A8%A1%E5%BC%8F%E6%90%AC%E5%85%A5.CS5V1m_f.png",r="/assets/DIST_US%E6%A8%A1%E5%BC%8F%E6%90%AC%E5%85%A5.BtSUb_ZZ.png",l="/assets/DIST_DS%E6%A8%A1%E5%BC%8F%E6%90%AC%E5%85%A5.iABPS4h9.png",p="/assets/Offset%E5%8A%9F%E8%83%BD%E7%A4%BA%E6%84%8F%E5%9B%BE.C4lnUZNZ.png",b=JSON.parse('{"title":"MaskReg搬入","description":"","frontmatter":{},"headers":[{"level":1,"title":"MaskReg搬入","slug":"maskreg搬入"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/Reg数据搬运/MaskReg搬入.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/Reg数据搬运/MaskReg搬入.md"}'),i={name:"api/SIMD-API/基础API/Reg矢量计算/Reg数据搬运/MaskReg搬入.md"};function o(_,t,g,c,h,A){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="maskreg搬入" tabindex="-1">MaskReg搬入 <a class="header-anchor" href="#maskreg搬入" aria-label="Permalink to &quot;MaskReg搬入&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Reg矢量计算数据搬运接口，适用于从UB或RegTensor搬入MaskReg。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// MaskReg搬入使用 AddrReg 存储偏移量</span></span>
<span class="line"><span>template &lt;typename T, MaskDist dist = MaskDist::DIST_NORM&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void LoadAlign(MaskReg&amp; mask, __ubuf__ T* srcAddr, AddrReg offset);</span></span>
<span class="line"><span>// MaskReg搬入POST_MODE_NORMAL 场景</span></span>
<span class="line"><span>template &lt;typename T, MaskDist dist = MaskDist::DIST_NORM&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void LoadAlign(MaskReg&amp; mask, __ubuf__ T* srcAddr);</span></span>
<span class="line"><span>// MaskReg搬入POST_MODE_UPDATE 场景</span></span>
<span class="line"><span>template &lt;typename T, PostLiteral postMode, MaskDist dist = MaskDist::DIST_NORM&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void LoadAlign(MaskReg&amp; mask, __ubuf__ T* &amp;srcAddr, int32_t offset);</span></span>
<span class="line"><span>// MaskReg从RegTensor搬入</span></span>
<span class="line"><span>template &lt;typename T = DefaultType, int16_t offset, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void MaskGenWithRegTensor(MaskReg&amp; dst, U&amp; srcReg);</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> MaskReg搬入使用AddrReg存储偏移量参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>输入</td><td>操作数数据类型。支持的数据类型为b8/b16/b32。</td></tr><tr><td>dist</td><td>输入</td><td>搬运模式， MaskDist类型。取值如下： DIST_NORM，对齐约束为VL/8Byte，正常模式，搬运VL/8Byte数据。DIST_US，对齐约束为VL/16Byte，上采样模式，搬运VL/16Byte数据，每bit重复一次。DIST_DS，对齐约束为min(32, VL/4)Byte，下采样模式，搬运VL/4Byte数据，每间隔1bit被舍弃。</td></tr><tr><td>mask</td><td>输出</td><td>目的操作数，类型为MaskReg。</td></tr><tr><td>srcAddr</td><td>输入/输出</td><td>源操作数在UB上的起始地址。</td></tr><tr><td>offset</td><td>输入</td><td>实际搬运UB起始地址为 srcAddr + offset。</td></tr></tbody></table><p><strong>表 2</strong> MaskReg搬入POST_MODE_NORMAL场景参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>输入</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为b8/b16/b32/b64。</td></tr><tr><td>dist</td><td>输入</td><td>搬运模式， MaskDist类型。取值如下： DIST_NORM，对齐约束为VL/8Byte，正常模式，搬运VL/8Byte数据。DIST_US，对齐约束为VL/16Byte，上采样模式，搬运VL/16Byte数据，每bit重复一次。DIST_DS，对齐约束为min(32, VL/4)Byte，下采样模式，搬运VL/4Byte数据，每间隔1bit被舍弃。</td></tr><tr><td>mask</td><td>输出</td><td>目的操作数，类型为MaskTensor。</td></tr><tr><td>srcAddr</td><td>输入/输出</td><td>源操作数在UB上的起始地址。</td></tr></tbody></table><p><strong>表 3</strong> MaskReg搬入POST_MODE_UPDATE场景参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>输入</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为b8/b16/b32/b64。</td></tr><tr><td>dist</td><td>输入</td><td>搬运模式， MaskDist类型。取值如下： DIST_NORM，对齐约束为VL/8Byte，正常模式，搬运VL/8Byte数据。DIST_US，对齐约束为VL/16Byte，上采样模式，搬运VL/16Byte数据，每bit重复一次。DIST_DS，对齐约束为min(32, VL/4)Byte，下采样模式，搬运VL/4Byte数据，每间隔1bit被舍弃。</td></tr><tr><td>postMode</td><td>输入</td><td>用于控制是否使能post update。 POST_MODE_NORMAL，正常场景，UB操作数地址不更新。 POST_MODE_UPDATE，POST_MODE_UPDATE场景使用，UB地址同时作为输入和输出，每次调用会更新。</td></tr><tr><td>mask</td><td>输出</td><td>目的操作数，类型为MaskTensor。</td></tr><tr><td>srcAddr</td><td>输入/输出</td><td>源操作数在UB上的起始地址。</td></tr><tr><td>offset</td><td>输入</td><td>当offset为int32_t类型时，POST_MODE_NORMAL与POST_MODE_UPDATE含义不一致。POST_MODE_NORMAL 场景：实际搬运UB起始地址为srcAddr + offset。POST_MODE_UPDATE 场景：实际搬运UB起始地址为srcAddr，搬运后执行地址更新 srcAddr += offset。</td></tr></tbody></table><p><strong>图 1</strong> DIST_NORM模式搬入<br><img src="`+d+'" alt="" title="DIST_NORM模式搬入"></p><p><strong>图 2</strong> DIST_US模式搬入<br><img src="'+r+'" alt="" title="DIST_US模式搬入"></p><p><strong>图 3</strong> DIST_DS模式搬入<br><img src="'+l+'" alt="" title="DIST_DS模式搬入"></p><p><strong>表 4</strong> MaskReg从RegTensor搬入参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>输入</td><td>操作数数据类型。支持的数据类型为b16/b32。</td></tr><tr><td>U</td><td>输入</td><td>源操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>dst</td><td>输出</td><td>目的操作数，类型为MaskTensor。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数，类型为RegTensor。</td></tr><tr><td>offset</td><td>输入</td><td>offset决定了srcReg中数据搬运的起始地址，当数据类型T为b16时，计算公式为offset* 16，由于VL为256Byte，因此此时offset取值范围为0-15，同理，T为b32数据类型时，计算公式为offset* 8，offset的取值范围为0-31。 当数据类型为B16时，dst[i] = srcReg[offset<em>VL/16 + i/2]，按bit位进行计算。 当数据类型为B32时，dst[i] = srcReg[offset</em>VL/32 + i/4],，按bit位进行计算。</td></tr></tbody></table><p><strong>图 4</strong> Offset功能示意图<br><img src="'+p+`" alt="" title="Offset功能示意图"></p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void LoadAlignVF(__ubuf__ T* dstAddr, __ubuf__ T* srcAddr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;;</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; ++i) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::AddrReg offset = AscendC::Reg::CreateAddrReg&lt;T&gt;(i, oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(mask, srcAddr, offset);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr, mask, offset);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>template &lt;typename T, int16_t offset&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void MaskGenWithRegTensorVF(__ubuf__ T* dstAddr, __ubuf__ T* srcAddr)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask = AscendC::Reg::CreateMask&lt;T&gt;();</span></span>
<span class="line"><span>    AscendC::Reg::LoadAlign(srcReg, srcAddr);</span></span>
<span class="line"><span>    AscendC::Reg::MaskGenWithRegTensor&lt;T, offset&gt;(mask, srcReg);</span></span>
<span class="line"><span>    AscendC::Reg::StoreAlign(dstAddr, mask);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,26)])])}const R=s(i,[["render",o]]);export{b as __pageData,R as default};
